package com.hbm.client.reactor.rbmk.failure;
import com.hbm.machine.reactor.rbmk.failure.*;import net.minecraft.client.Minecraft;import net.minecraft.world.level.levelgen.Heightmap;import net.minecraft.world.phys.Vec3;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.fml.event.lifecycle.FMLClientSetupEvent;import net.neoforged.neoforge.client.event.EntityRenderersEvent;
@EventBusSubscriber(modid="hbm",value=Dist.CLIENT,bus=EventBusSubscriber.Bus.MOD)public final class RbmkFailureClient {
 @SubscribeEvent public static void renderers(EntityRenderersEvent.RegisterRenderers event){event.registerEntityRenderer(RbmkFailureContent.SPEAR.get(),DigammaSpearRenderer::new);}@SubscribeEvent public static void setup(FMLClientSetupEvent event){DigammaSpear.CLIENT_AIR=spear->{var world=spear.level();double y=world.getHeight(Heightmap.Types.WORLD_SURFACE,(int)Math.floor(spear.getX()),(int)Math.floor(spear.getZ()))+2;receive(new RbmkFailureEffects.Packet(false,spear.getX(),y,spear.getZ(),5));};}
 public static void receive(RbmkFailureEffects.Packet packet){var mc=Minecraft.getInstance();var world=mc.level;if(world==null)return;if(packet.flame()){mc.particleEngine.add(new RbmkFlameParticle(world,packet.x(),packet.y(),packet.z(),packet.amount()));return;}var vector=new Vec3(2,0,0).yRot(world.random.nextFloat()*(float)Math.PI*2F);for(int i=0;i<packet.amount();i++){mc.particleEngine.add(new RbmkDigammaSmoke(world,packet.x(),packet.y(),packet.z(),vector.x,vector.z));vector=vector.yRot((float)Math.PI*2F/packet.amount());}}
}
